2	import { updateSession } from "@/lib/supabase/middleware";
3	
4	export async function middleware(request: NextRequest) {
5	  // Kiosk画面へのアクセスを保護
6	  if (request.nextUrl.pathname.startsWith("/kiosk")) {
7	    const { searchParams } = request.nextUrl;
8	    const token = searchParams.get("token");
9	    const kioskToken = process.env.KIOSK_ACCESS_TOKEN;
10	
11	    if (!kioskToken) {
12	        console.error("KIOSK_ACCESS_TOKEN is not set on the server.");
13	        // 本番環境ではエラーページにリダイレクトすることを推奨
14	        return new NextResponse("Kiosk is not configured.", { status: 500 });
15	    }
16	
17	    if (token !== kioskToken) {
18	      // トークンが不正な場合は、ページの存在を悟られないようにダッシュボードへリダイレクト
19	      const url = request.nextUrl.clone();
20	      url.pathname = "/dashboard";
21	      url.search = ''; // クエリパラメータをクリア
22	      return NextResponse.redirect(url);
23	    }
24	    
25	    // トークンが有効な場合は、そのままKioskページを表示
26	    return NextResponse.next();
27	  }
28	
29	  // OAuth セッションチェック（/login と /auth/* 以外）
30	  const isPublicPath = request.nextUrl.pathname.startsWith('/login') || 
31	                       request.nextUrl.pathname.startsWith('/auth/');
32	  
33	  if (!isPublicPath) {
34	    const oauthUserId = request.cookies.get('oauth_user_id')?.value;
35	    const oauthToken = request.cookies.get('oauth_access_token')?.value;
36	    
37	    // OAuth セッションがある場合はそのまま通す
38	    if (oauthUserId && oauthToken) {
39	      return NextResponse.next();
40	    }
41	    
42	    // OAuth セッションがない場合はログインへリダイレクト
43	    const url = request.nextUrl.clone();
44	    url.pathname = "/login";
45	    return NextResponse.redirect(url);
46	  }
47	
48	  // 他のすべてのルートでSupabaseのセッションを更新（後方互換性のため残す）
49	  return await updateSession(request);
50	}
